"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Home, FileText, UserCircle, Calendar, Users, Settings } from "lucide-react";
import { useUser } from "@stackframe/stack";
import Topbar from "@/components/Topbar";
import DashboardContainer from "@/components/DashboardContainer";
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
} from "@/components/ui/sidebar";

interface Interview {
  id: number;
  role: string;
  interview_type: string;
  experience_level: string;
  num_questions: number;
  questions: string[];
  responses: string[];
  feedback: object;
  created_at: string;
}

export default function DashboardPage() {
  const user = useUser();
  const router = useRouter();
  const [isScrolled, setIsScrolled] = useState(false);
  const [interviews, setInterviews] = useState<Interview[]>([]);
  const [loading, setLoading] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [chatbotOpen, setChatbotOpen] = useState(false);

  // Interview generation form state
  const [role, setRole] = useState("");
  const [interviewType, setInterviewType] = useState("");
  const [experienceLevel, setExperienceLevel] = useState("");
  const [numQuestions, setNumQuestions] = useState(5);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 10);
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const handleSignOut = async () => {
    await user?.signOut();
    router.push("/");
  };

  // Redirect if not signed in
  useEffect(() => {
    if (!user) {
      router.push("/auth/signin");
    }
  }, [user, router]);

  // Fetch interviews on component mount
  useEffect(() => {
    fetchInterviews();
  }, []);

  const fetchInterviews = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/interviews/');
      if (response.ok) {
        const data = await response.json();
        setInterviews(data);
      }
    } catch (error) {
      console.error('Error fetching interviews:', error);
    } finally {
      setLoading(false);
    }
  };

  const generateInterview = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!role || !interviewType || !experienceLevel) {
      alert('Please fill in all fields');
      return;
    }

    setGenerating(true);
    try {
      const response = await fetch('/api/interviews/create/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          role,
          type: interviewType,
          level: experienceLevel,
          num_questions: numQuestions,
        }),
      });

      if (response.ok) {
        const newInterview = await response.json();
        setInterviews([newInterview, ...interviews]);
        // Reset form
        setRole("");
        setInterviewType("");
        setExperienceLevel("");
        setNumQuestions(5);
      } else {
        alert('Error generating interview');
      }
    } catch (error) {
      console.error('Error generating interview:', error);
      alert('Error generating interview');
    } finally {
      setGenerating(false);
    }
  };

  const handleInterviewGenerated = (interviewData: Interview) => {
    setInterviews([interviewData, ...interviews]);
    setChatbotOpen(false);
  };

  if (!user) {
    return null;
  }

  return (
    <SidebarProvider>
      <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900 text-foreground font-sans">
      {/* Animated Background */}
      <div className="fixed inset-0 bg-[radial-gradient(ellipse_at_top,_var(--tw-gradient-stops))] from-purple-900/20 via-slate-900 to-slate-900 pointer-events-none"></div>
      <div className="fixed inset-0 bg-grid-white/[0.02] bg-[size:50px_50px] pointer-events-none"></div>

      <Sidebar className="bg-gradient-to-br from-purple-900/50 to-slate-900/50 border-r border-purple-500/20">
        <SidebarHeader className="border-b border-purple-500/20">
          <SidebarMenu>
            <SidebarMenuItem>
              <SidebarMenuButton className="text-purple-300 hover:bg-purple-500/20 hover:text-white transition-all duration-200">
                <Home className="text-purple-400" />
                <span>Dashboard</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
            <SidebarMenuItem>
              <SidebarMenuButton className="text-purple-300 hover:bg-purple-500/20 hover:text-white transition-all duration-200">
                <FileText className="text-purple-400" />
                <span>Interviews</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
            <SidebarMenuItem>
              <SidebarMenuButton className="text-purple-300 hover:bg-purple-500/20 hover:text-white transition-all duration-200">
                <UserCircle className="text-purple-400" />
                <span>Profile</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarHeader>
        <SidebarContent>
          <SidebarGroup>
            <SidebarGroupLabel className="text-purple-200/70">Navigation</SidebarGroupLabel>
            <SidebarGroupContent>
              <SidebarMenu>
                <SidebarMenuItem>
                  <SidebarMenuButton className="text-purple-300 hover:bg-purple-500/20 hover:text-white transition-all duration-200">
                    <Calendar className="text-purple-400" />
                    <span>Recent Interviews</span>
                  </SidebarMenuButton>
                </SidebarMenuItem>
                <SidebarMenuItem>
                  <SidebarMenuButton className="text-purple-300 hover:bg-purple-500/20 hover:text-white transition-all duration-200">
                    <Users className="text-purple-400" />
                    <span>Community</span>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
        <SidebarFooter className="border-t border-purple-500/20">
          <SidebarMenu>
            <SidebarMenuItem>
              <SidebarMenuButton className="text-purple-300 hover:bg-purple-500/20 hover:text-white transition-all duration-200">
                <Settings className="text-purple-400" />
                <span>Settings</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarFooter>
      </Sidebar>

      <SidebarInset>
        {/* Navbar */}
      <nav
        className={`fixed w-full z-50 transition-all duration-300 ${
          isScrolled
            ? "bg-gradient-to-r from-slate-900/90 to-purple-900/90 backdrop-blur-md py-3 shadow-xl border-b border-purple-500/30"
            : "py-6"
        }`}
      >
        <div className="container mx-auto px-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <SidebarTrigger className="text-purple-400 hover:text-white hover:bg-purple-500/20 transition-all duration-200" />
            <div className="flex items-center gap-2">
              <h1 className="text-3xl font-bold text-white">
                AI<span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-pink-400">NEX</span>
              </h1>
              <span className="text-sm inline-flex items-center bg-gradient-to-r from-purple-500/20 to-pink-500/20 backdrop-blur-sm border border-purple-500/30 rounded-full px-3 py-1 text-purple-200">
                Dashboard
              </span>
            </div>
          </div>

          <div className="hidden lg:flex items-center space-x-4">
            <div className="flex items-center gap-2 text-gray-300 bg-slate-800/50 px-3 py-2 rounded-full border border-purple-500/20">
              <User size={16} className="text-purple-400" />
              <span className="text-sm">Welcome, {user.primaryEmail || "User"}</span>
            </div>
            <Button
              variant="outline"
              className="border-purple-500/50 text-purple-300 hover:bg-purple-500/20 hover:text-white hover:border-purple-400 transition-all duration-200"
              onClick={() => router.push("/dashboard")}
            >
              Dashboard
            </Button>
            <Button
              variant="outline"
              className="border-gray-500/50 text-gray-300 hover:bg-gray-500/20 hover:text-white hover:border-gray-400 transition-all duration-200"
              onClick={handleSignOut}
            >
              <LogOut size={16} className="mr-2" />
              Sign Out
            </Button>
          </div>
        </div>
      </nav>

      {/* Interview Chatbot */}
      <InterviewChatbot
        isOpen={chatbotOpen}
        onClose={() => setChatbotOpen(false)}
        onInterviewGenerated={handleInterviewGenerated}
        onToggle={() => setChatbotOpen(true)}
      />

      <main className="relative z-10 pt-24 pb-12">
        <div className="container mx-auto px-6">
          {/* Welcome Section */}
          <section className="mb-12 animate-fade-in relative">
            <div className="text-center">
              <h1 className="font-display text-4xl md:text-6xl text-white mb-4">
                Welcome to your{' '}
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 via-pink-400 to-purple-400 animate-pulse">
                  AI<span className="text-purple-300">NEX</span>
                </span>{' '}
                Dashboard
              </h1>
              <p className="text-gray-300 text-xl max-w-2xl mx-auto mb-6">
                Monitor your AI usage, manage your models, and explore powerful features all in one place.
              </p>
              <div className="flex justify-center gap-4">
                <Button className="bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 text-white px-6 py-3 rounded-full shadow-lg hover:shadow-xl transition-all duration-200">
                  <Plus className="mr-2 size-5" />
                  Create Interview
                </Button>
                <Button variant="outline" className="border-purple-500/50 text-purple-300 hover:bg-purple-500/20 hover:text-white px-6 py-3 rounded-full transition-all duration-200">
                  <Eye className="mr-2 size-5" />
                  View Analytics
                </Button>
              </div>
            </div>
            <div className="absolute inset-0 bg-gradient-to-r from-purple-500/10 to-pink-500/10 rounded-3xl blur-3xl -z-10"></div>
          </section>

          {/* Recent Interviews */}
          <section className="mb-12 animate-fade-in">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-purple-500/20 rounded-lg">
                <Calendar className="size-6 text-purple-400" />
              </div>
              <h2 className="text-3xl font-display text-white">
                Recent{' '}
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-pink-400">
                  Interviews
                </span>
              </h2>
            </div>
            {loading ? (
              <div className="text-center text-gray-400">Loading interviews...</div>
            ) : interviews.length > 0 ? (
              <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                {interviews.slice(0, 6).map((interview) => (
                  <Card key={interview.id} className="p-6 bg-gradient-to-br from-slate-800/60 to-purple-900/30 border-purple-500/30 hover:border-purple-500/50 hover:shadow-lg hover:shadow-purple-500/20 transition-all duration-300 animate-fade-in group">
                    <CardHeader>
                      <CardTitle className="text-white text-lg group-hover:text-purple-300 transition-colors duration-200">{interview.role}</CardTitle>
                      <CardDescription className="text-gray-300 group-hover:text-gray-200 transition-colors duration-200">
                        {interview.interview_type} • {interview.experience_level} • {interview.num_questions} questions
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <div className="text-gray-400 text-sm mb-4 group-hover:text-gray-300 transition-colors duration-200">
                        Created: {new Date(interview.created_at).toLocaleDateString()}
                      </div>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          className="bg-gradient-to-r from-purple-600 to-purple-700 hover:from-purple-700 hover:to-purple-800 text-white shadow-md hover:shadow-lg transition-all duration-200"
                          onClick={() => router.push(`/interview/${interview.id}`)}
                        >
                          View Questions
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          className="border-red-500/50 text-red-400 hover:bg-red-500/20 hover:text-white hover:border-red-400 transition-all duration-200"
                          onClick={() => {
                            if (confirm('Are you sure you want to delete this interview?')) {
                              // Delete interview logic here
                            }
                          }}
                        >
                          Delete
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            ) : (
              <div className="text-center text-gray-400 py-12">
                <MessageSquare className="size-16 text-gray-600 mx-auto mb-4" />
                <p className="text-xl">No interviews generated yet</p>
                <p className="text-gray-500">Create your first interview using the form above</p>
              </div>
            )}
          </section>

          {/* Community Interviews */}
          <section className="animate-fade-in">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-purple-500/20 rounded-lg">
                <Users className="size-6 text-purple-400" />
              </div>
              <h2 className="text-3xl font-display text-white">
                Community{' '}
                <span className="text-transparent bg-clip-text bg-gradient-to-r from-purple-400 to-pink-400">
                  Interviews
                </span>
              </h2>
            </div>
            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
              {/* Sample community interviews */}
              <Card className="p-6 bg-gradient-to-br from-slate-800/60 to-purple-900/30 border-purple-500/30 hover:border-purple-500/50 hover:shadow-lg hover:shadow-purple-500/20 transition-all duration-300 animate-fade-in group">
                <CardHeader>
                  <CardTitle className="text-white text-lg group-hover:text-purple-300 transition-colors duration-200">Frontend Developer</CardTitle>
                  <CardDescription className="text-gray-300 group-hover:text-gray-200 transition-colors duration-200">
                    Technical • Intermediate • 8 questions
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="text-gray-400 text-sm mb-4 group-hover:text-gray-300 transition-colors duration-200">
                    Created by: Community User
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    className="w-full border-purple-500/50 text-purple-300 hover:bg-purple-500/20 hover:text-white hover:border-purple-400 transition-all duration-200"
                  >
                    View Interview
                  </Button>
                </CardContent>
              </Card>

              <Card className="p-6 bg-gradient-to-br from-slate-800/60 to-purple-900/30 border-purple-500/30 hover:border-purple-500/50 hover:shadow-lg hover:shadow-purple-500/20 transition-all duration-300 animate-fade-in group">
                <CardHeader>
                  <CardTitle className="text-white text-lg group-hover:text-purple-300 transition-colors duration-200">Product Manager</CardTitle>
                  <CardDescription className="text-gray-300 group-hover:text-gray-200 transition-colors duration-200">
                    Behavioral • Advanced • 10 questions
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="text-gray-400 text-sm mb-4 group-hover:text-gray-300 transition-colors duration-200">
                    Created by: Community User
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    className="w-full border-purple-500/50 text-purple-300 hover:bg-purple-500/20 hover:text-white hover:border-purple-400 transition-all duration-200"
                  >
                    View Interview
                  </Button>
                </CardContent>
              </Card>

              <Card className="p-6 bg-gradient-to-br from-slate-800/60 to-purple-900/30 border-purple-500/30 hover:border-purple-500/50 hover:shadow-lg hover:shadow-purple-500/20 transition-all duration-300 animate-fade-in group">
                <CardHeader>
                  <CardTitle className="text-white text-lg group-hover:text-purple-300 transition-colors duration-200">Data Scientist</CardTitle>
                  <CardDescription className="text-gray-300 group-hover:text-gray-200 transition-colors duration-200">
                    Technical • Beginner • 6 questions
                  </CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="text-gray-400 text-sm mb-4 group-hover:text-gray-300 transition-colors duration-200">
                    Created by: Community User
                  </div>
                  <Button
                    size="sm"
                    variant="outline"
                    className="w-full border-purple-500/50 text-purple-300 hover:bg-purple-500/20 hover:text-white hover:border-purple-400 transition-all duration-200"
                  >
                    View Interview
                  </Button>
                </CardContent>
              </Card>
            </div>
          </section>
        </div>
      </main>
      </SidebarInset>
      </div>
    </SidebarProvider>
  );
}